/**
 * Pure batching / truncation math for gemini_ocr.
 *
 * Kept deliberately free of I/O (no fs, no network, no Gemini SDK) so it can
 * be unit tested without mocking anything — this is the piece the tests must
 * cover per the task spec.
 *
 * Design:
 *   - `page_range` is expanded into a flat, deduplicated, ascending list of
 *     1-based page numbers by the caller (see parsePageRange in gemini_ocr.ts).
 *   - PER_CALL_PAGE_CAP bounds how many pages ONE tool invocation will ever
 *     OCR, regardless of how large page_range is. This exists because C1
 *     forces strictly sequential per-batch Gemini calls (never parallel), so
 *     an unbounded page_range on a single invocation would make one tool
 *     call take arbitrarily long / risk timing out the MCP transport. A
 *     truncated invocation returns a `next_start_index` so the caller can
 *     re-invoke starting where the last one left off (Quality Bar #19).
 *   - Within one invocation, pages are further split into GEMINI_BATCH_SIZE
 *     chunks so each individual Gemini call stays small (5-8 pages), and
 *     those chunks are processed strictly in order (C1) — nextGeminiBatch()
 *     is the function that walks chunks one at a time.
 */

/**
 * Max pages one `gemini_ocr` tool invocation will process before truncating
 * and asking the caller to re-invoke with a later start index. Chosen so a
 * single invocation (which may run several sequential Gemini batches, see
 * GEMINI_BATCH_SIZE) stays well under typical MCP client timeouts even at
 * worst-case per-page OCR latency (~5-10s/page for dense scanned text).
 * 40 pages / GEMINI_BATCH_SIZE(=8) = 5 sequential Gemini calls per invocation,
 * a few minutes of wall time — safe headroom, still large enough to be useful
 * for a typical chapter-length request.
 */
export const PER_CALL_PAGE_CAP = 40;

/**
 * Pages sent to Gemini per vision call. 5-8 is the sane range called out in
 * the task spec; we pick 6 as the midpoint: large enough to amortize the
 * fixed per-call overhead (auth, system prompt, schema) over multiple pages,
 * small enough that a single bad/dense page doesn't blow the whole batch's
 * token budget or make truncation-on-failure lose too much completed work.
 */
export const GEMINI_BATCH_SIZE = 6;

export interface BatchPlan {
  /** 1-based page numbers this invocation will process, in order. */
  pagesToProcess: number[];
  /** True if total_requested_pages > PER_CALL_PAGE_CAP and this invocation
   *  could not process all of them. */
  truncated: boolean;
  /** 1-based index (within the full requested page list, not the document)
   *  of the next page to start from on a follow-up call, if truncated. */
  nextStartIndex?: number;
  /** Human-readable summary to prefix/suffix the tool's response text with,
   *  per Quality Bar #19, e.g.
   *  "12 of 40 pages processed; call again with page_range starting at page 13." */
  truncationMessage?: string;
}

export class BatchValidationError extends Error {}

/**
 * Compute which pages one `gemini_ocr` invocation should process, given the
 * full ordered list of requested document page numbers and where a prior
 * (truncated) invocation left off.
 *
 * @param requestedPages full ascending list of 1-based document page numbers
 *   the caller asked for (already expanded from page_range).
 * @param alreadyProcessedCount how many of `requestedPages`, from the start,
 *   have already been handled by a prior truncated call. 0 for a fresh call.
 * @param perCallCap max pages this invocation may process (defaults to
 *   PER_CALL_PAGE_CAP; exposed as a param purely for testability).
 */
export function planBatch(
  requestedPages: number[],
  alreadyProcessedCount = 0,
  perCallCap: number = PER_CALL_PAGE_CAP,
): BatchPlan {
  const total = requestedPages.length;
  if (total === 0) {
    throw new BatchValidationError('page_range resolved to zero pages.');
  }
  if (alreadyProcessedCount < 0 || alreadyProcessedCount > total) {
    throw new BatchValidationError(
      `already_processed_count (${alreadyProcessedCount}) is out of range for ${total} requested pages.`,
    );
  }
  if (alreadyProcessedCount === total) {
    // Nothing left to do — caller re-invoked after the job actually finished.
    return { pagesToProcess: [], truncated: false };
  }

  const remaining = total - alreadyProcessedCount;
  const take = Math.min(remaining, perCallCap);
  const pagesToProcess = requestedPages.slice(
    alreadyProcessedCount,
    alreadyProcessedCount + take,
  );
  const truncated = alreadyProcessedCount + take < total;

  const plan: BatchPlan = { pagesToProcess, truncated };
  if (truncated) {
    const processedSoFar = alreadyProcessedCount + take;
    plan.nextStartIndex = processedSoFar; // 0-based index into requestedPages
    const nextPageNumber = requestedPages[processedSoFar];
    plan.truncationMessage =
      `${processedSoFar} of ${total} pages processed; ` +
      `call again with page_range starting at page ${nextPageNumber}.`;
  }
  return plan;
}

/**
 * Split a page list into strictly-sequential Gemini call chunks. Callers
 * MUST await each chunk's Gemini call before starting the next — this
 * function only computes the chunk boundaries, it does not enforce
 * sequencing (that's the caller's job in gemini_ocr.ts, per C1).
 */
export function chunkForGeminiCalls(
  pages: number[],
  batchSize: number = GEMINI_BATCH_SIZE,
): number[][] {
  if (batchSize <= 0) {
    throw new BatchValidationError(`batchSize must be positive, got ${batchSize}.`);
  }
  const chunks: number[][] = [];
  for (let i = 0; i < pages.length; i += batchSize) {
    chunks.push(pages.slice(i, i + batchSize));
  }
  return chunks;
}

/**
 * Parse a page_range string like "1-20" or "5,7,9-12" into an ascending,
 * deduplicated list of 1-based page numbers, validated against totalPages.
 * Returns the full 1..totalPages range if `rangeStr` is undefined/empty.
 */
export function parsePageRange(rangeStr: string | undefined, totalPages: number): number[] {
  if (totalPages <= 0) {
    throw new BatchValidationError(`totalPages must be positive, got ${totalPages}.`);
  }
  if (!rangeStr || rangeStr.trim() === '') {
    return Array.from({ length: totalPages }, (_, i) => i + 1);
  }
  const pages = new Set<number>();
  const parts = rangeStr.split(',').map((p) => p.trim()).filter(Boolean);
  if (parts.length === 0) {
    throw new BatchValidationError(`page_range "${rangeStr}" contained no page tokens.`);
  }
  for (const part of parts) {
    const rangeMatch = /^(\d+)-(\d+)$/.exec(part);
    const singleMatch = /^(\d+)$/.exec(part);
    if (rangeMatch) {
      const start = parseInt(rangeMatch[1], 10);
      const end = parseInt(rangeMatch[2], 10);
      if (start < 1 || end < 1 || start > end) {
        throw new BatchValidationError(
          `page_range segment "${part}" is not a valid ascending range.`,
        );
      }
      if (end > totalPages) {
        throw new BatchValidationError(
          `page_range segment "${part}" exceeds document length (${totalPages} pages).`,
        );
      }
      for (let p = start; p <= end; p++) pages.add(p);
    } else if (singleMatch) {
      const p = parseInt(singleMatch[1], 10);
      if (p < 1) {
        throw new BatchValidationError(`page_range segment "${part}" must be >= 1.`);
      }
      if (p > totalPages) {
        throw new BatchValidationError(
          `page_range segment "${part}" exceeds document length (${totalPages} pages).`,
        );
      }
      pages.add(p);
    } else {
      throw new BatchValidationError(
        `page_range segment "${part}" is malformed; expected "N" or "N-M".`,
      );
    }
  }
  return Array.from(pages).sort((a, b) => a - b);
}
